function toYAML(x,indent=0){
  const pad=' '.repeat(indent);
  if(Array.isArray(x)){
    if(!x.length)return '[]';
    return x.map(v=>{
      if(v===null||typeof v!=='object')return pad+'- '+scalar(v);
      if(!Object.keys(v).length)return pad+'- '+(Array.isArray(v)?'[]':'{}');
      const nested=toYAML(v,indent+2).split('\n');
      return pad+'- '+nested[0].slice(indent+2)+(nested.length>1?'\n'+nested.slice(1).join('\n'):'');
    }).join('\n');
  }
  if(x&&typeof x==='object'){
    if(!Object.keys(x).length)return '{}';
    return Object.entries(x).map(([k,v])=>v&&typeof v==='object'&&Object.keys(v).length?pad+k+':\n'+toYAML(v,indent+2):pad+k+': '+(v&&typeof v==='object'?Array.isArray(v)?'[]':'{}':scalar(v))).join('\n');
  }
  return pad+scalar(x);
}
