  if(d.type==='delete'){title=r.uid?'删除实例':'删除未部署草稿';const checks=r.uid?publicationChecks(r,r.remote??r.saved,true):[];body=`<p>名称：<strong>${esc(r.crName||r.saved.name||'未命名实例')}</strong></p><p class="help">命名空间：<code>${esc(r.remote?.namespace??r.saved.namespace)}</code></p>${r.uid?'<p>确认删除对应 CR，保留平台配置和管理历史。原 CR 与工作负载/Pod 全部核验消失后才显示完成。</p>':'<p>此实例尚未部署，只删除草稿，不触及集群。</p>'}${r.kind==='Agent'&&r.remote?.storage==='PVC'?`<div class="alert"><strong>实际已生效 PVC 策略</strong><br>whenScaled: ${r.livePolicy.whenScaled} · whenDeleted: ${r.livePolicy.whenDeleted}<br>${r.livePolicy.whenDeleted==='Retain'?'PVC 将保留，需要在集群侧清理。':'受影响 PVC 将进入删除流程，结果仍需独立核验。'}</div>`:''}${checks.filter(c=>!c.ok).map(c=>`<div class="alert bad">${esc(c.why)}</div>`).join('')}`;footer=`<button data-action="close-dialog">取消</button><button class="danger" data-action="confirm-delete" ${checks.some(c=>!c.ok)?'disabled':''}>确认${r.uid?'删除实例':'删除草稿'}</button>`;narrow=true;}
  if(d.type==='register'){title='注册集群';body=`<div class="fields"><div class="field"><label>集群显示名称</label><input id="register-name" value="kind-new"></div><div class="field"><label>所属用户</label><select id="register-owner">${model.accounts.filter(a=>a.active).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></div><div class="field full"><label>演示 kubeconfig context</label><select id="register-context"><option value="new">kind-new · 内嵌 CA 与认证信息（模拟）</option><option value="duplicate">kind-local · 已注册集群（模拟）</option><option value="exec">依赖 exec 的 context（模拟，不支持）</option></select><div class="help">原型不读取文件或真实凭据，仅选择预设 context 演示。</div></div><div class="field full"><label class="row"><input type="checkbox" id="register-limited">演示组件 CRD/权限不完整，登记为能力受限集群</label></div></div><div class="alert info">检查连通、TLS、有效访问身份与集群 UID；组件能力不足可以登记，受影响组件不能下发。</div>`;footer='<button data-action="close-dialog">取消</button><button class="primary" data-action="confirm-register">核验并登记（模拟）</button>';}
  if(d.type==='transfer'){const c=model.clusters.find(c=>c.id===d.id);title='调整集群归属';body=`<p>${esc(c.name)} 当前归属 ${esc(model.accounts.find(a=>a.id===c.owner)?.name)}。</p><select id="transfer-owner">${model.accounts.filter(a=>a.active).map(a=>`<option value="${a.id}" ${a.id===c.owner?'selected':''}>${esc(a.name)}</option>`).join('')}</select>${clusterBusy(c)?'<div class="alert bad" style="margin-top:12px">该集群仍有未结束变更任务，暂不可转移。</div>':'<p class="help">转移后原所属用户失去权限，新所属用户接收配置与历史。</p>'}`;footer=`<button data-action="close-dialog">取消</button><button class="primary" data-action="confirm-transfer" ${clusterBusy(c)?'disabled':''}>确认转移</button>`;narrow=true;}
