  if(action==='confirm-archive'){if(!c||clusterBusy(c))return toast('集群有未结束变更，不能注销');c.active=!c.active;c.connected=c.active;model.instances.filter(r=>r.clusterId===c.id).forEach(r=>{r.currentKnown=false;recordHistory(r,c.active?'集群重新启用，等待重新读取；不自动下发':'集群已注销，停止同步；配置与组件保留');});toast(c.active?'演示集群已重新启用':'演示集群已注销，组件保留');}
  if(action==='confirm-account'){const id=document.getElementById('account-id').value.trim(),name=document.getElementById('account-name').value.trim(),isAdmin=document.getElementById('account-admin').checked;if(!id||!name)return toast('请填写用户名与显示名称');if(model.accounts.some(a=>a.id===id))return toast('用户名已存在');model.accounts.push({id,name,active:true,role:isAdmin?'admin':'owner'});toast('演示账号已创建');}
