document.addEventListener('click',event=>{const picker=document.querySelector('.cluster-picker');if(picker?.open&&!picker.contains(event.target))picker.open=false;const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const {action,id,key,path,index,version}=button.dataset,r=instance();
  if(action==='previous-variant')return cycleVariant(-1);if(action==='next-variant')return cycleVariant(1);if(action==='reset')return setScenario('normal');
  if(action==='close-dialog'){ui.dialog=null;return renderDialog();}if(action==='close-drawer'){ui.drawer=false;return render();}
  if(!actor()?.active||!ui.session)return toast('当前会话失效，请切换演示身份');
  if(action==='select-cluster'){if(!visibleClusters().some(c=>c.id===id))return;button.closest('.cluster-picker').open=false;selectCluster(id);document.querySelector('.cluster-picker summary')?.focus({preventScroll:true});return;}if(action==='clear-instance-filters'){ui.filters={name:'',category:'',component:'',status:''};return render();}if(action==='toggle-archived'){ui.showArchived=!ui.showArchived;return render();}if(action==='page'){ui.page=key;ui.dialog=null;return render();}
  if(action==='cluster'||action==='manage-cluster'){if(!visibleClusters().some(c=>c.id===id))return;ui.page='instances';return selectCluster(id);}
  if(['select-instance','open-drawer','choose-step','preview-row'].includes(action)){chooseInstance(id);if(action==='preview-row')openPublication();return;}
  if(action==='current-draft'){ui.configVersion=null;ui.tab='config';return render();}if(action==='open-version')return openVersion(id,Number(version));if(action==='tab'){ui.configVersion=null;ui.tab=key;return render();}if(action==='step'){ui.step=Number(index);return render();}
  if(action==='retry')return openRetry();if(action==='confirm-retry')return confirmRetry();if(action==='save')return saveDraft();if(action==='preview')return openPublication();if(action==='cover-preview')return openPublication(true);if(action==='confirm-publish')return confirmPublication();
  if(action==='add-instance'){ui.page='add-instance';ui.newCategory=null;ui.drawer=false;ui.dialog=null;return render();}if(action==='select-category'){ui.newCategory=key;return render();}if(action==='create-component')return createInstance(id);if(action==='delete-row'){const target=model.instances.find(item=>item.id===id);if(!mayEdit(target)||activeTask(target))return;ui.instanceId=id;ui.drawer=false;return openDelete();}if(action==='clone'&&r)return createInstance(r.kind,true);
  if(action==='delete')return openDelete();if(action==='confirm-delete')return confirmDelete();if(action==='cancel')return cancelTask();if(action==='refresh')return refresh();if(action==='refresh-all'){model.instances.filter(r=>r.clusterId===ui.clusterId&&!r.deleted).forEach(r=>refresh(r,true));return toast('本集群各实例已独立核验');}
  if(action==='reload-draft'&&r){r.savedRevision++;r.saved.resources.cpuRequest='180';r.edit=clone(r.saved);r.demo='normal';ui.scenario='normal';r.notice='已加载最新草稿；请在此基线上继续修改';return render();}
  if(['add-label','add-expression','remove-row','add-endpoint','remove-endpoint'].includes(action)){if(!mayEdit(r))return;touchInstance(r);if(action==='add-label')get(r.edit,path).push({key:'',value:''});if(action==='add-expression')get(r.edit,path).push({key:'',operator:'In',values:''});if(action==='remove-row')get(r.edit,path).splice(Number(index),1);if(action==='add-endpoint'){const e=newEndpoint();e.name='';r.edit.remote.push(e);}if(action==='remove-endpoint')r.edit.remote.splice(Number(index),1);return render();}
  if(['register','transfer','credentials','archive','new-account'].includes(action)){if(!adminAction())return;ui.dialog={type:action,id};return renderDialog();}
  if(action.startsWith('confirm-'))return confirmAdminDialog(action);if(['toggle-account','toggle-admin','reset-password'].includes(action))return adminAccountAction(id,action);
});
function bindInput(element){const r=instance(),path=element.dataset.bind;if(!path||!mayEdit(r)||element.disabled)return;let value=element.type==='checkbox'?element.checked:element.value;if(path.endsWith('.inherit')){value=value==='true';const role=get(r.edit,path.replace(/\.inherit$/,''));if(!value&&!role.everIndependent){role.resources=clone(r.edit.resources);role.everIndependent=true;}}
  if(path==='name'){const filtered=String(value).replace(/[^a-z0-9.-]/g,'');if(filtered!==value){element.value=filtered;value=filtered;toast('名称不支持中文或其他特殊字符，请使用小写字母、数字、连字符或点');}}if(get(r.edit,path)!==value)touchInstance(r);set(r.edit,path,value);delete r.errors[path];updateEditStatus();
}
document.addEventListener('input',event=>{if(event.target.dataset.filter==='name')return updateInstanceFilter(event.target);if(event.target.matches('[data-bind]'))bindInput(event.target);});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.filter)return updateInstanceFilter(el);if(el.dataset.control==='role')return selectRole(el.value);if(el.dataset.control==='cluster')return selectCluster(el.value);if(el.dataset.control==='scenario')return setScenario(el.value);if(el.dataset.collector){const r=instance();if(!mayEdit(r))return;const name=el.dataset.collector;touchInstance(r);r.edit.collectors=el.checked?[...new Set([...r.edit.collectors,name])]:r.edit.collectors.filter(x=>x!==name);delete r.errors.collectorMode;updateEditStatus();return;}if(el.dataset.namespaceValue){const r=instance();if(!mayEdit(r))return;touchInstance(r);const selected=lines(r.edit.namespaceNames),name=el.dataset.namespaceValue;r.edit.namespaceNames=(el.checked?[...new Set([...selected,name])]:selected.filter(n=>n!==name)).join('\n');delete r.errors.namespaceNames;el.closest('.namespace-picker').querySelector('summary').textContent=lines(r.edit.namespaceNames).join('、')||'请选择 namespace（可多选）';updateNamespacePreview();updateEditStatus();return;}if(el.dataset.bind){bindInput(el);render();}});
document.addEventListener('toggle',event=>{if(event.target.matches?.('.cluster-picker'))event.target.querySelector('summary').setAttribute('aria-expanded',String(event.target.open));},true);
document.addEventListener('focusout',event=>{const picker=event.target.closest('.cluster-picker');if(picker&&event.relatedTarget&&!picker.contains(event.relatedTarget))picker.open=false;});
function clusterPickerKey(event){const picker=event.target.closest('.cluster-picker');if(!picker)return false;const summary=picker.querySelector('summary');if(event.key==='Escape'){event.preventDefault();picker.open=false;summary.focus({preventScroll:true});return true;}if(!['ArrowDown','ArrowUp','Home','End'].includes(event.key))return false;event.preventDefault();picker.open=true;const options=[...picker.querySelectorAll('[role="option"]')];let index=options.indexOf(document.activeElement);index=event.key==='Home'?0:event.key==='End'?options.length-1:index<0?Math.max(0,options.findIndex(option=>option.getAttribute('aria-selected')==='true')):(index+(event.key==='ArrowDown'?1:-1)+options.length)%options.length;options[index]?.focus({preventScroll:true});options[index]?.scrollIntoView({block:'nearest'});return true;}
document.addEventListener('keydown',event=>{if(clusterPickerKey(event))return;if(event.key==='Escape'){ui.dialog=null;renderDialog();return;}if(!['ArrowLeft','ArrowRight'].includes(event.key)||event.target.closest('input,textarea,select,[contenteditable],.cluster-picker')||event.altKey||event.metaKey||event.ctrlKey)return;event.preventDefault();cycleVariant(event.key==='ArrowRight'?1:-1);});
